let highlighted;function randomHighlighted(){const e=new Set;for(;e.size!=6;)e.add(Math.round(Math.random()*(highlighted.length-1)));document.getElementById("highlightedItems").innerHTML=Array.from(e).map(e=>formatItem(highlighted[e])).join("")}document.getElementById("highlightedButton").addEventListener("click",async e=>{if(e.preventDefault(),!highlighted){const e=await fetch(new URL(document.URL).pathname+"index.json"),t=await e.json();highlighted=t.highlighted}randomHighlighted()})